import { useState, useEffect, useCallback } from "react";
import { soutenanceApi } from "../api/api";
import StatsBar from "./Statsbar.js";

const STATUT_CONFIG = {
  PLANIFIEE: { label: "Planifiée", color: "#3b82f6", bg: "rgba(59,130,246,0.1)"  },
  TERMINEE:  { label: "Terminée",  color: "#10b981", bg: "rgba(16,185,129,0.1)"  },
  ANNULEE:   { label: "Annulée",   color: "#ef4444", bg: "rgba(239,68,68,0.1)"   },
  EN_COURS:  { label: "En cours",  color: "#f59e0b", bg: "rgba(245,158,11,0.1)"  },
};

function StatusBadge({ statut }) {
  const s = STATUT_CONFIG[statut] || STATUT_CONFIG.PLANIFIEE;
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 6,
      background: s.bg, color: s.color,
      padding: "4px 10px", borderRadius: 20, fontSize: 12, fontWeight: 500,
    }}>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: s.color }} />
      {s.label}
    </span>
  );
}

function Field({ label, value }) {
  return (
    <div>
      <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 2 }}>
        {label}
      </div>
      <div style={{ fontSize: 13, color: "var(--text)" }}>{value || "—"}</div>
    </div>
  );
}

export default function PlanningFinal() {
  const [soutenances, setSoutenances] = useState([]);
  const [loading, setLoading]         = useState(true);
  const [error, setError]             = useState(null);
  const [search, setSearch]           = useState("");
  const [dateFilter, setDateFilter]   = useState("");
  const [expandedId, setExpandedId]   = useState(null);
  const [resultatForm, setResultatForm] = useState({});
  const [actionLoading, setActionLoading] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = dateFilter
        ? await soutenanceApi.getPlanningParDate(dateFilter)
        : await soutenanceApi.getPlanningFinal();
      setSoutenances(data);
      setError(null);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, [dateFilter]);

  useEffect(() => { load(); }, [load]);

  const handlePlanifierAuto = async () => {
    setActionLoading("auto");
    try {
      await soutenanceApi.planifierAuto();
      await load();
    } catch (e) { setError(e.message); }
    finally { setActionLoading(null); }
  };

  const handleResultat = async (id) => {
    const r = resultatForm[id];
    if (!r?.note) { setError("La note est obligatoire."); return; }
    setActionLoading(id);
    try {
      await soutenanceApi.enregistrerResultat(id, {
        note: parseFloat(r.note),
        observations: r.observations || "",
        present: r.present !== false,
      });
      setExpandedId(null);
      await load();
    } catch (e) { setError(e.message); }
    finally { setActionLoading(null); }
  };

  const filtered = soutenances.filter(s => {
    if (!search) return true;
    const q = search.toLowerCase();
    return (
      s.binome?.etudiant1?.nom?.toLowerCase().includes(q) ||
      s.binome?.etudiant2?.nom?.toLowerCase().includes(q) ||
      s.affectation?.sujet?.titre?.toLowerCase().includes(q) ||
      s.creneau?.salle?.toLowerCase().includes(q)
    );
  });

  const terminees = soutenances.filter(s => s.statut === "TERMINEE");
  const moyenne = terminees.length > 0
    ? (terminees.reduce((acc, s) => acc + (s.note || 0), 0) / terminees.length).toFixed(1)
    : "—";

  return (
    <div style={{ animation: "fadeIn 0.3s ease" }}>
      <style>{`
        @keyframes fadeIn { from { opacity:0; transform:translateY(8px) } to { opacity:1; transform:translateY(0) } }
        .s-card { transition: border-color 0.15s; }
        .s-card:hover { border-color: var(--border2) !important; }
        .btn-action { transition: opacity 0.15s, transform 0.1s; }
        .btn-action:hover { opacity: 0.85; }
        .btn-action:active { transform: scale(0.97); }
      `}</style>

      <div style={{ marginBottom: 28 }}>
        <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.08em", marginBottom: 6 }}>
          Phase 4
        </div>
        <h1 style={{ fontSize: 24, fontWeight: 600, color: "var(--text)", letterSpacing: "-0.4px" }}>
          Planning des soutenances
        </h1>
      </div>

      {/* Stats */}
      <StatsBar stats={[
        { label: "Total",         value: soutenances.length,                                       color: "var(--text)"  },
        { label: "Planifiées",    value: soutenances.filter(s => s.statut === "PLANIFIEE").length, total: soutenances.length, color: "var(--accent)" },
        { label: "Terminées",     value: terminees.length,                                          total: soutenances.length, color: "var(--green)" },
        { label: "Moy. générale", value: moyenne,                                                   color: "var(--amber)" },
      ]} />

      {/* Toolbar */}
      <div style={{ display: "flex", gap: 10, marginBottom: 20, flexWrap: "wrap", alignItems: "center" }}>
        <input
          placeholder="Rechercher binôme, sujet, salle..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{
            flex: 1, minWidth: 220, padding: "8px 14px", borderRadius: 8,
            border: "1px solid var(--border2)", background: "var(--surface2)",
            color: "var(--text)", outline: "none",
          }}
        />
        <input type="date"
          value={dateFilter}
          onChange={e => setDateFilter(e.target.value)}
          style={{
            padding: "8px 12px", borderRadius: 8, border: "1px solid var(--border2)",
            background: "var(--surface2)", color: "var(--text)", outline: "none",
          }}
        />
        {dateFilter && (
          <button className="btn-action"
            onClick={() => setDateFilter("")}
            style={{
              padding: "8px 12px", borderRadius: 8, border: "1px solid var(--border)",
              background: "transparent", color: "var(--muted2)", fontSize: 13,
            }}>
            Effacer
          </button>
        )}
        <button className="btn-action"
          onClick={handlePlanifierAuto}
          disabled={actionLoading === "auto"}
          style={{
            padding: "8px 16px", borderRadius: 8, border: "none",
            background: "var(--accent)", color: "#fff", fontSize: 13, fontWeight: 500,
            opacity: actionLoading === "auto" ? 0.6 : 1,
          }}>
          {actionLoading === "auto" ? "En cours..." : "Planification auto"}
        </button>
      </div>

      {error && (
        <div style={{
          background: "rgba(239,68,68,0.1)", border: "1px solid rgba(239,68,68,0.3)",
          color: "#ef4444", borderRadius: "var(--radius)", padding: "10px 14px",
          fontSize: 13, marginBottom: 16,
        }}>
          {error}
        </div>
      )}

      {loading && <LoadingState />}

      {!loading && filtered.length === 0 && (
        <div style={{ textAlign: "center", padding: "60px 0", color: "var(--muted)" }}>
          Aucune soutenance trouvée.
        </div>
      )}

      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {filtered.map(s => {
          const isOpen = expandedId === s.id;
          return (
            <div key={s.id} className="s-card"
              style={{
                background: "var(--surface)", border: "1px solid var(--border)",
                borderRadius: "var(--radius-lg)", overflow: "hidden",
              }}>
              {/* Row principal */}
              <div
                onClick={() => setExpandedId(isOpen ? null : s.id)}
                style={{
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                  padding: "18px 24px", cursor: "pointer",
                }}>
                <div style={{ display: "flex", flexDirection: "column", gap: 3 }}>
                  <div style={{ fontSize: 14, fontWeight: 500, color: "var(--text)" }}>
                    {s.binome?.etudiant1?.nom} & {s.binome?.etudiant2?.nom}
                  </div>
                  <div style={{ fontSize: 12, color: "var(--muted)" }}>
                    {s.affectation?.sujet?.titre}
                  </div>
                </div>

                <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                  <div style={{ textAlign: "right", fontSize: 12, color: "var(--muted)", fontFamily: "'DM Mono', monospace" }}>
                    <div>{s.creneau?.date}</div>
                    <div>{s.creneau?.heureDebut} · {s.creneau?.salle}</div>
                  </div>
                  {s.note != null && (
                    <div style={{
                      fontFamily: "'DM Mono', monospace", fontSize: 15, fontWeight: 500,
                      color: s.note >= 10 ? "var(--green)" : "var(--red)",
                    }}>
                      {s.note}/20
                    </div>
                  )}
                  <StatusBadge statut={s.statut} />
                  <span style={{ color: "var(--muted)", fontSize: 12, userSelect: "none" }}>
                    {isOpen ? "▲" : "▼"}
                  </span>
                </div>
              </div>

              {/* Détail expandable */}
              {isOpen && (
                <div style={{ borderTop: "1px solid var(--border)", padding: "20px 24px", background: "var(--surface2)" }}>
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: "14px 32px", marginBottom: 20 }}>
                    <Field label="Encadrant" value={s.affectation?.sujet?.encadrant?.nom} />
                    <Field label="Jury"      value={s.jury?.map(j => j.nom).join(", ")} />
                    <Field label="Salle"     value={s.creneau?.salle} />
                    <Field label="Heure début" value={s.creneau?.heureDebut} />
                    <Field label="Heure fin"   value={s.creneau?.heureFin} />
                    <Field label="Présence"    value={s.present == null ? "—" : s.present ? "Présent" : "Absent"} />
                  </div>

                  {s.observations && (
                    <div style={{
                      background: "var(--surface)", borderRadius: 8, padding: "10px 14px",
                      fontSize: 13, color: "var(--muted2)", marginBottom: 16,
                      borderLeft: "3px solid var(--border2)",
                    }}>
                      {s.observations}
                    </div>
                  )}

                  {/* Formulaire résultat */}
                  {s.statut === "PLANIFIEE" && (
                    <div style={{ borderTop: "1px solid var(--border)", paddingTop: 16 }}>
                      <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 10, textTransform: "uppercase", letterSpacing: "0.05em" }}>
                        Enregistrer le résultat
                      </div>
                      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
                        <input
                          type="number" min="0" max="20" step="0.5"
                          placeholder="Note /20"
                          value={resultatForm[s.id]?.note || ""}
                          onChange={e => setResultatForm(p => ({ ...p, [s.id]: { ...p[s.id], note: e.target.value } }))}
                          style={{
                            width: 100, padding: "7px 10px", borderRadius: 8,
                            border: "1px solid var(--border2)", background: "var(--surface)",
                            color: "var(--text)", outline: "none",
                          }}
                        />
                        <input
                          placeholder="Observations du jury..."
                          value={resultatForm[s.id]?.observations || ""}
                          onChange={e => setResultatForm(p => ({ ...p, [s.id]: { ...p[s.id], observations: e.target.value } }))}
                          style={{
                            flex: 1, minWidth: 180, padding: "7px 12px", borderRadius: 8,
                            border: "1px solid var(--border2)", background: "var(--surface)",
                            color: "var(--text)", outline: "none",
                          }}
                        />
                        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 13, color: "var(--muted2)", cursor: "pointer" }}>
                          <input type="checkbox" defaultChecked
                            onChange={e => setResultatForm(p => ({ ...p, [s.id]: { ...p[s.id], present: e.target.checked } }))}
                          />
                          Présent
                        </label>
                        <button className="btn-action"
                          onClick={() => handleResultat(s.id)}
                          disabled={actionLoading === s.id}
                          style={{
                            padding: "7px 16px", borderRadius: 8, border: "none",
                            background: "var(--green)", color: "#fff", fontSize: 13, fontWeight: 500,
                            opacity: actionLoading === s.id ? 0.6 : 1,
                          }}>
                          {actionLoading === s.id ? "..." : "Enregistrer"}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function LoadingState() {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      {[1,2,3].map(i => (
        <div key={i} style={{
          background: "var(--surface)", border: "1px solid var(--border)",
          borderRadius: "var(--radius-lg)", height: 72, opacity: 1 - i * 0.2,
        }} />
      ))}
    </div>
  );
}
